Object.assign(uiText,uiComplete);
function translateTextNode(node){
 const raw=node.nodeValue;if(!raw||lang==='ar')return;
 let out=raw;
 const entries=Object.entries(uiText).filter(([k,v])=>v&&v[lang]).sort((a,b)=>b[0].length-a[0].length);
 for(const [ar,vals] of entries) if(out.includes(ar)) out=out.split(ar).join(vals[lang]);
 // Translate remaining fixed English headings/labels used by the owner workspace.
 for(const [en,vals] of Object.entries(uiLatin)){const val=vals&&vals[lang];if(val!==undefined&&val!==''&&out.includes(en))out=out.split(en).join(val);}
 if(lang==='en') for(const [ar,vals] of entries){} // Arabic is handled above.
 if(out!==raw)node.nodeValue=out;
}
function translateRenderedUI(root=document.getElementById('view')){
 if(!root||lang==='ar')return;
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(w.nextNode())nodes.push(w.currentNode);nodes.forEach(translateTextNode);
 root.querySelectorAll('input[placeholder],textarea[placeholder],input[aria-label],textarea[aria-label],button[title],*[title]').forEach(el=>{
  for(const attr of ['placeholder','aria-label','title']){const raw=el.getAttribute(attr);if(!raw)continue;let fake=document.createTextNode(raw);translateTextNode(fake);if(fake.nodeValue!==raw)el.setAttribute(attr,fake.nodeValue);}
 });
}
let uiTranslationObserver=null;
function enableUITranslationObserver(){if(uiTranslationObserver||!window.MutationObserver)return;uiTranslationObserver=new MutationObserver(ms=>{if(!ME||lang==='ar')return;ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1&&!n.closest('.login-screen'))translateRenderedUI(n)}))});uiTranslationObserver.observe(document.body,{childList:true,subtree:true})}

