function toggleDashboardLanguageMenu(e){e?.stopPropagation();const c=document.getElementById('languageControl');if(!c)return;const open=c.classList.toggle('open');const b=c.querySelector('.language-trigger');if(b)b.setAttribute('aria-expanded',String(open));}
