async function loadTeacherReadiness(){
 if(!ME||ME.role!=='teacher')return null;
 try{return await api('/api/teacher/setup-status')}catch(e){return null}
}
function teacherReadinessBannerHTML(st){
 if(!st)return '';
 const missing=(st.items||[]).filter(x=>!x.ready);
 if(!missing.length)return '';
 const n=missing.length;
 return `<div class="teacher-readiness-strip" role="status"><div class="teacher-readiness-main"><span class="teacher-readiness-dot"></span><div><b>استكمال تهيئة فضاء الأستاذ</b><span>توجد ${n} ${n===1?'معطى يحتاج إلى الاستكمال':'معطيات تحتاج إلى الاستكمال'}.</span></div></div><button class="teacher-readiness-action" onclick="openTeacherSetup()">عرض التفاصيل</button></div>`;
}
async function openTeacherSetup(){
 const st=await loadTeacherReadiness();
 if(!st)return;
 const items=(st.items||[]);
 const m=document.createElement('div');m.className='modal';
 const labelFor=x=>x.label;
 m.innerHTML=`<div class="modal-box teacher-setup-modal"><div class="modal-head"><div><span class="eyebrow">EPS PILOT</span><h3>تهيئة فضاء الأستاذ</h3></div><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div>
 <div class="teacher-setup-intro"><b>${st.ready?'فضاء الأستاذ جاهز للعمل':'قبل بدء العمل، يرجى استكمال المعطيات الأساسية'}</b><p>${st.ready?'جميع المتطلبات الأساسية متوفرة.':'تُدخل كل معلومة مرة واحدة، ثم تُستخدم تلقائياً في الوحدات المرتبطة بها.'}</p></div>
 <div class="teacher-setup-list">${items.map(x=>`<div class="teacher-setup-item ${x.ready?'ready':'missing'}"><div class="setup-status-icon">${x.ready?'✓':'!'}</div><div class="setup-item-body"><b>${labelFor(x)}</b><span>${x.reason}</span></div>${x.ready?`<span class="setup-state ready">مكتمل</span>`:`<button class="ghost mini" onclick="teacherSetupGo('${x.action}');this.closest('.modal').remove()">استكمال</button>`}</div>`).join('')}</div>
 <div class="teacher-setup-footer"><span>${items.filter(x=>x.ready).length} / ${items.length} مكتمل</span><button class="primary" onclick="this.closest('.modal').remove();page('resources')">فتح التهيئة والبيانات المرجعية</button></div></div>`;
 document.body.appendChild(m);
}
window.openTeacherSetup=openTeacherSetup;
window.teacherSetupGo=function(action){if(action==='grading'||action==='pedagogy'||action==='holidays')page('resources');else page(action)};
async function showTeacherFirstStart(){
 if(!ME||ME.role!=='teacher')return;
 let seen=false;try{seen=localStorage.getItem('epsTeacherStartSeen')==='1'}catch{}
 if(seen)return;
 const st=await loadTeacherReadiness(); if(!st)return;
 const assignedClasses=(st.items||[]).find(x=>x.key==='classes');
 const assignedTimetable=(st.items||[]).find(x=>x.key==='timetable');
 const hasAssigned=assignedClasses?.ready||assignedTimetable?.ready;
 const both=assignedClasses?.ready&&assignedTimetable?.ready;
 const lead=both?'تم إسناد الأقسام واستعمال الزمن إلى فضاء الأستاذ من طرف المنسق.':hasAssigned?'تم توفير جزء من المعطيات الأساسية إلى فضاء الأستاذ من طرف المنسق.':'لم يتم إسناد الأقسام أو استعمال الزمن إلى فضاء الأستاذ بعد.';
 const sub=both?'يرجى استكمال المعطيات المتبقية، مثل شبكة التنقيط والمراجع التربوية، حسب ما هو مطلوب.':hasAssigned?'يرجى استكمال العناصر المتبقية من الخانة الأصلية لكل معطى.':'يرجى إضافة المعطيات الأساسية من الخانات المخصصة لها، ثم متابعة العمل.';
 const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-first-start"><div class="modal-head"><div><span class="eyebrow">EPS PILOT · بداية العمل</span><h2>تهيئة فضاء الأستاذ</h2></div></div><div class="teacher-start-message"><div class="teacher-start-mark">${both?'✓':'i'}</div><div><h3>${lead}</h3><p>${sub}</p></div></div><div class="teacher-start-principle"><b>كيف تعمل المنصة؟</b><span>كل معلومة تُدخل مرة واحدة في مكانها الأصلي، ثم تنتقل تلقائياً إلى الحصص والدفاتر والتقويم والتقارير المرتبطة بها.</span></div><div class="teacher-start-actions"><button class="primary" onclick="this.closest('.modal').remove();try{localStorage.setItem('epsTeacherStartSeen','1')}catch{};openTeacherSetup()">متابعة التهيئة</button><button class="ghost" onclick="this.closest('.modal').remove();try{localStorage.setItem('epsTeacherStartSeen','1')}catch{}">الدخول إلى فضاء الأستاذ</button></div></div>`;document.body.appendChild(m);
}
window.showTeacherFirstStart=showTeacherFirstStart;
