function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';A.innerHTML=`<div class="layout ${lang==='ar'?'rtl':''}"><div class="mobile-nav-overlay" id="mobileNavDrawer" onclick="if(event.target===this)closeMobileNav()"><div class="mobile-nav-panel"><div class="mobile-nav-head"><b>EPS PILOT</b><button type="button" class="mobile-nav-close" onclick="closeMobileNav()">×</button></div><nav class="nav">${nav().map(([k,lab])=>`<button data-mobile-page="${k}">${L(lab)}</button>`).join('')}</nav><button class="danger mobile-logout" onclick="logout()">${L('logout')}</button></div></div><aside class="sidebar"><div class="brand"><img src="assets/eps-pilot-logo.png"><div><b>EPS PILOT</b><div class="role">${roleName(ME.role)}</div></div></div><nav class="nav">${nav().map(([k,lab])=>`<button data-page="${k}">${L(lab)}</button>`).join('')}</nav><button class="danger" style="width:100%;margin-top:15px" onclick="logout()">${L('logout')}</button></aside><main class="main"><header class="topbar"><div class="mobile-top-left"><button type="button" class="mobile-menu-btn" aria-label="Menu" onclick="toggleMobileNav()">☰</button><b>${L('welcome')}، ${esc(ME.full_name)}</b></div><div class="top-actions"><div class="language-control" id="languageControl"><button type="button" class="language-trigger" aria-haspopup="true" aria-expanded="false" onclick="toggleDashboardLanguageMenu(event)"><span class="lang-globe">◎</span><span class="language-current">${lang==='ar'?'العربية':lang==='fr'?'Français':'English'}</span><span class="language-chevron">⌄</span></button><div class="language-menu" role="menu"><button type="button" class="language-option ${lang==='ar'?'selected':''}" onclick="setLang('ar')"><span>العربية</span><b>AR</b></button><button type="button" class="language-option ${lang==='fr'?'selected':''}" onclick="setLang('fr')"><span>Français</span><b>FR</b></button><button type="button" class="language-option ${lang==='en'?'selected':''}" onclick="setLang('en')"><span>English</span><b>EN</b></button></div></div><div class="profile-chip"><span class="profile-avatar">${esc((ME.full_name||'E').slice(0,1))}</span><div><b>${esc(ME.full_name)}</b><small>${roleName(ME.role)}</small></div></div></div></header><div id="teacherReadinessGlobal"></div><section class="content" id="view"></section></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{closeMobileNav();page(b.dataset.page)});document.querySelectorAll('[data-mobile-page]').forEach(b=>b.onclick=()=>{closeMobileNav();page(b.dataset.mobilePage)});page('dashboard');if(ME.role==='teacher'){loadTeacherReadiness().then(st=>{const g=document.getElementById('teacherReadinessGlobal');if(g)g.innerHTML=teacherReadinessBannerHTML(st)});}if(ME.force_password_change){setTimeout(()=>{if(typeof forcePassword==='function')forcePassword()},180)}if(ME.billing_only){setTimeout(showSubscriptionPaywall,260)}}

function forcePassword(){
 let m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${L('change')}</h3></div><div class="notice danger-note">${LI('firstPasswordNotice')}</div><form id="firstPw"><div class="field"><label>${L('current')}</label><input name=current type=password required autocomplete="current-password"></div><div class="field"><label>${L('newp')}</label><input name=next type=password minlength=8 required autocomplete="new-password"></div><div class="field"><label>${lang==='ar'?'تأكيد كلمة المرور الجديدة':lang==='fr'?'Confirmer le nouveau mot de passe':'Confirm new password'}</label><input name=confirm type=password minlength=8 required autocomplete="new-password"></div><button class="primary">${L('submit')}</button></form></div>`;document.body.appendChild(m);document.getElementById('firstPw').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.next!==b.confirm){toast(lang==='ar'?'كلمتا المرور الجديدتان غير متطابقتين.':lang==='fr'?'Les nouveaux mots de passe ne correspondent pas.':'The new passwords do not match.');return}try{await api('/api/password',{method:'POST',body:JSON.stringify({current:b.current,next:b.next})});ME.force_password_change=false;m.remove();toast(LI('passwordChanged'))}catch(x){toast(x.message)}}}

