async function smartCoordinatorDashboard(v){const d=await api('/api/coordinator/intelligence');v.innerHTML=`<div class="owner-dashboard"><div class="owner-hero-pro platform-hero"><div><span class="eyebrow">EPS PILOT · COORDINATOR INTELLIGENCE</span><h1>${lang==='ar'?'لوحة القيادة الذكية للمؤسسة':'Smart institution dashboard'}</h1><p>${lang==='ar'?'صورة موحدة عن الأساتذة والأقسام والحصص ومؤشرات المتابعة.':'Unified view of teachers, classes, sessions and monitoring signals.'}</p></div></div><div class="owner-kpi-grid"><div class="kpi blue"><span>${lang==='ar'?'الأساتذة':'Teachers'}</span><b>${d.teachers.length}</b></div><div class="kpi green"><span>${lang==='ar'?'الأقسام':'Classes'}</span><b>${d.classes.length}</b></div><div class="kpi purple"><span>${lang==='ar'?'الحصص':'Sessions'}</span><b>${d.sessions}</b></div><div class="kpi orange"><span>${lang==='ar'?'التقارير':'Reports'}</span><b>${d.reports}</b></div></div><div class="owner-main-grid"><div class="owner-panel"><div class="panel-title"><h2>${lang==='ar'?'الأساتذة':'Teachers'}</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الأستاذ':'Teacher'}</th><th>${lang==='ar'?'الحصص':'Sessions'}</th><th>${lang==='ar'?'التقويم':'Assessments'}</th><th>${lang==='ar'?'سجلات الغياب':'Absence entries'}</th></tr></thead><tbody>${d.teachers.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${x.sessions}</td><td>${x.assessments}</td><td>${x.absences}</td></tr>`).join('')}</tbody></table></div></div><div class="owner-panel"><div class="panel-title"><h2>${lang==='ar'?'الأقسام التي تحتاج متابعة':'Classes needing attention'}</h2></div>${d.risk_classes.slice(0,8).map(x=>`<div class="activity"><div><b>${esc(x.name)}</b><small>${esc(x.teacher_name||'—')} · ${x.students} ${lang==='ar'?'تلميذ':'students'}</small></div><span>${x.absence_rate}%</span></div>`).join('')||'<div class="empty">—</div>'}</div></div></div>`}
async function smartInspectorMonitoring(v){const d=await api('/api/inspector/intelligence');v.innerHTML=`<div class="owner-dashboard"><div class="owner-hero-pro platform-hero"><div><span class="eyebrow">EPS PILOT · INSPECTOR INTELLIGENCE</span><h1>${lang==='ar'?'لوحة المؤشرات الذكية للمفتش':'Smart inspector dashboard'}</h1><p>${lang==='ar'?'مؤشرات إجمالية فقط داخل المؤسسات المسندة، دون أسماء التلاميذ أو معطيات الحضور الفردية.':'Aggregate indicators only within assigned institutions; no individual student or attendance data.'}</p></div></div><div class="owner-kpi-grid">${[['institutions','المؤسسات'],['teachers','الأساتذة'],['classes','الأقسام'],['students','التلاميذ'],['sessions','الحصص']].map(([k,l])=>`<div class="kpi blue"><span>${lang==='ar'?l:k}</span><b>${d.summary[k]||0}</b></div>`).join('')}</div><div class="owner-panel"><div class="panel-title"><h2>${lang==='ar'?'المؤسسات المسندة':'Assigned institutions'}</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'المؤسسة':'Institution'}</th><th>${lang==='ar'?'الأساتذة':'Teachers'}</th><th>${lang==='ar'?'الأقسام':'Classes'}</th><th>${lang==='ar'?'التلاميذ':'Students'}</th><th>${lang==='ar'?'الحصص':'Sessions'}</th></tr></thead><tbody>${d.institutions.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.teachers}</td><td>${x.classes}</td><td>${x.students}</td><td>${x.sessions}</td></tr>`).join('')}</tbody></table></div></div></div>`}
