function parseTimetableText(raw){
 const out=[];String(raw||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).forEach(line=>{const p=line.split(/\t|;|,/).map(x=>x.trim());if(!p.length||/^(jour|day|اليوم)/i.test(p[0]))return;let day=p[0],map={'الأحد':0,'الاحد':0,'dimanche':0,'sunday':0,'الاثنين':1,'lundi':1,'monday':1,'الثلاثاء':2,'mardi':2,'tuesday':2,'الأربعاء':3,'mercredi':3,'wednesday':3,'الخميس':4,'jeudi':4,'thursday':4,'الجمعة':5,'vendredi':5,'friday':5,'السبت':6,'samedi':6,'saturday':6};let d=map[String(day).toLowerCase()];if(d===undefined)d=/^[0-6]$/.test(day)?Number(day):null;let times=p.filter(x=>/^\d{1,2}:\d{2}$/.test(x));if(d!==null&&times.length>=2)out.push({day_of_week:d,start_time:times[0],end_time:times[1],class_name:p.find(x=>classesNameGuess(x))||p[3]||'',activity:p.slice(2).join(' ')||'EPS'});});return out;
}
