function dlText(name,text,mime='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printHtml(title,body,dir=lang==='ar'?'rtl':'ltr'){const w=window.open('','_blank');w.document.write(`<html dir="${dir}"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial;margin:18px;color:#123}h1,h2{color:#075eaa}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #9bbbd5;padding:7px}th{background:#dceefe}.kpi{display:inline-block;padding:12px 18px;border:1px solid #b8d5ea;border-radius:12px;margin:5px}.note{padding:12px;background:#eef8ff;border-radius:10px}@media print{body{margin:8mm}}</style></head><body>${body}<script>window.print()<\/script></body></html>`);w.document.close()}
window.teacherClasses = async function teacherClasses(v){const c=TC(),rows=await api('/api/classes'),students=await api('/api/students');window.__teacherClasses=rows;const count={};students.forEach(s=>count[s.class_id]=(count[s.class_id]||0)+1);v.innerHTML=teacherHero(c.classes,c.assigned)+`<div class="teacher-panel"><div class="section-head"><div><h3>${c.classes}</h3><p class="muted">${lang==='ar'?'كل قسم مرتبط بلائحة التلاميذ الخاصة به. يمكن إضافة التلاميذ يدوياً أو باستيراد Excel/CSV. تظهر الأقسام المسندة من المؤسسة أو المرتبطة باستعمال الزمن تلقائياً.':'Chaque classe possède directement sa liste d’élèves. Ajoutez-la manuellement ou par Excel/CSV.'}</p></div><div class="actions"><button class="ghost" onclick="teacherClassImport()">Excel / CSV</button><button class="primary" onclick="teacherClassForm()">＋ ${lang==='ar'?'إضافة قسم':'Ajouter une classe'}</button></div></div><div class="teacher-card-grid">${rows.map(r=>`<div class="class-card"><div class="class-card-top"><span class="class-level">${esc(r.level||'')}</span><b>${esc(r.name)}</b></div><p>${esc(r.year_label||'')}</p><div class="class-card-meta"><span>${c.students}: <b>${count[r.id]||0}</b></span><button class="ghost mini" onclick="teacherClassForm('${r.id}')">${c.edit}</button><button class="danger mini" onclick="teacherClassDelete('${r.id}')">${lang==='ar'?'حذف':'Supprimer'}</button></div><div class="actions" style="margin-top:10px"><button class="primary mini" onclick="classStudentsManager('${r.id}')">${lang==='ar'?'تلاميذ القسم':'Élèves'}</button><button class="ghost mini" onclick="teacherMassarImportForClass('${r.id}')">Excel / CSV</button><button class="ghost mini" onclick="openClassReports('${r.id}')">${lang==='ar'?'تقرير القسم':'Rapport classe'}</button></div></div>`).join('')||`<div class="empty">${c.no}</div>`}</div></div>`}
window.teacherMassarImportForClass = function teacherMassarImportForClass(cid){window.__teacherClasses=window.__teacherClasses||[];teacherMassarImport(cid)}
window.teacherMassarImport = function teacherMassarImport(cid0){const c=TC(),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal"><div class="modal-head"><div><h3>${lang==='ar'?'إضافة لائحة التلاميذ':'Ajouter la liste des élèves'}</h3><p class="muted">${lang==='ar'?'اختار Excel/CSV أو لصق سريع من Excel.':'Choose Excel/CSV or paste directly from Excel.'}</p></div><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form><div class="field"><label>${c.class}</label><select name="class_id" required>${(window.__teacherClasses||[]).map(x=>`<option value="${x.id}" ${cid0===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Excel / CSV</label><input id="massarFile" type="file" accept=".xlsx,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><div class="field"><label>${lang==='ar'?'لصق سريع من Excel':'Paste from Excel'}</label><textarea id="massarPaste" rows="8" placeholder="Massar\tPrénom\tNom\n123456789\tAhmed\tAlaoui"></textarea></div><div class="actions"><button type="button" class="ghost" onclick="downloadMassarTemplate()">${lang==='ar'?'تحميل نموذج Excel/CSV':'Download template'}</button><button class="primary">${lang==='ar'?'إضافة التلاميذ':'Importer'}</button></div></form></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),class_id=fd.get('class_id'),file=m.querySelector('#massarFile').files[0],raw=m.querySelector('#massarPaste').value.trim();try{let r;if(file){r=await api('/api/students/import-file',{method:'POST',body:JSON.stringify({class_id,filename:file.name,data:await fileToBase64(file)})})}else{const rows=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const a=line.split(/\t|;|,/).map(x=>x.trim());if(/^(massar|رقم مسار)$/i.test(a[0]))return null;return {massar_number:a[0],first_name:a[1]||'',last_name:a[2]||''}}).filter(Boolean);r=await api('/api/students/import',{method:'POST',body:JSON.stringify({class_id,rows})})}m.remove();toast(`${lang==='ar'?'تمت الإضافة: ': 'Imported: '}${r.added||0} · ${lang==='ar'?'تحديث: ':'updated: '}${r.updated||0}`);page('classes')}catch(x){toast(x.message)}}}
window.classStudentsManager = async function classStudentsManager(cid){const cls=(await api('/api/classes')).find(x=>x.id===cid),all=await api('/api/students?class_id='+encodeURIComponent(cid)),c=TC(),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal wide"><div class="modal-head"><div><span class="eyebrow">${esc(cls?.name||'')}</span><h3>${lang==='ar'?'تلاميذ القسم':'Élèves de la classe'}</h3></div><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="actions"><button class="primary" onclick="studentManualForm('${cid}')">＋ ${lang==='ar'?'إضافة تلميذ يدوياً':'Ajouter manuellement'}</button><button class="ghost" onclick="teacherMassarImportForClass('${cid}');this.closest('.modal').remove()">Excel / CSV</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Massar</th><th>${c.student}</th><th>${L('actions')}</th></tr></thead><tbody>${all.map(s=>`<tr><td>${esc(s.massar_number)}</td><td>${esc(s.first_name+' '+s.last_name)}</td><td><button class="ghost mini" onclick="showStudent360ById('${s.id}')">360°</button></td></tr>`).join('')||`<tr><td colspan="3" class="empty">${c.no}</td></tr>`}</tbody></table></div></div>`;document.body.appendChild(m)}
window.studentManualForm = function studentManualForm(cid){const c=TC(),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal"><div class="modal-head"><h3>${lang==='ar'?'إضافة تلميذ':'Ajouter un élève'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field"><label>Massar</label><input name="massar_number" required></div><div class="field"><label>${lang==='ar'?'الاسم':'Prénom'}</label><input name="first_name" required></div><div class="field"><label>${lang==='ar'?'النسب':'Nom'}</label><input name="last_name" required></div><div class="field"><label>${lang==='ar'?'تاريخ الازدياد':'Date de naissance'}</label><input name="dob" type="date"></div><div class="field"><label>${lang==='ar'?'الجنس':'Genre'}</label><select name="gender"><option value="">—</option><option value="M">M</option><option value="F">F</option></select></div><div class="full"><button class="primary">${c.save}</button></div></form></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/students',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),class_id:cid})});m.remove();toast(c.save);page('classes')}catch(x){toast(x.message)}}}
window.teacherPlanning = async function teacherPlanning(v){const c=TC(),rows=await api('/api/plans'),classes=await api('/api/classes');window.__teacherPlans=rows;window.__teacherClasses=classes;v.innerHTML=teacherHero(c.planning,c.assigned)+`<div class="teacher-panel"><div class="section-head"><div><h3>${c.planning}</h3><p class="muted">${lang==='ar'?'التخطيط السنوي هو الأصل للوحدات والجذاذات والتتبع.':'Le plan annuel alimente les unités, les fiches et le suivi.'}</p></div><button class="primary" onclick="teacherPlanForm()">＋ ${c.add}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${c.title}</th><th>${c.class}</th><th>${lang==='ar'?'السنة':'Année'}</th><th>${c.status}</th><th>${lang==='ar'?'الإسناد':'Assignment'}</th><th>${L('actions')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b></td><td>${esc(r.teacher_name||r.institution_name||'—')}</td><td>${esc(r.school_year||'')}</td><td>${esc(r.status||'draft')}</td><td><button class="ghost mini" onclick="teacherPlanForm('${r.id}')">${c.edit}</button> <button class="danger mini" onclick="teacherPlanDelete('${r.id}')">${lang==='ar'?'حذف':'Supprimer'}</button> <button class="ghost mini" onclick="planReport('${r.id}')">${lang==='ar'?'تقرير':'Rapport'}</button></td></tr>`).join('')||`<tr><td colspan="5" class="empty">${c.no}</td></tr>`}</tbody></table></div></div>`}
window.teacherPlanForm = function teacherPlanForm(id0){const c=TC(),x=(window.__teacherPlans||[]).find(a=>a.id===id0),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal"><div class="modal-head"><h3>${id0?c.edit:c.add} · ${c.planning}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field full"><label>${c.title}</label><input name="title" value="${esc(x?.title||'Plan annuel EPS')}" required></div><div class="field"><label>${lang==='ar'?'السنة الدراسية':'Année scolaire'}</label><input name="school_year" value="${esc(x?.school_year||'2026-2027')}"></div><div class="field"><label>${c.status}</label><select name="status"><option value="draft">draft</option><option value="active">active</option><option value="completed">completed</option></select></div><div class="full"><button class="primary">${c.save}</button></div></form></div>`;document.body.appendChild(m);if(x)m.querySelector('[name=status]').value=x.status||'draft';m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));await api(id0?'/api/plans/'+id0:'/api/plans',{method:id0?'PUT':'POST',body:JSON.stringify({...b,teacher_id:ME.id,institution_id:ME.institution_id})});m.remove();page('planning')}catch(z){toast(z.message)}}}
window.teacherPlanDelete = async function teacherPlanDelete(id0){if(!confirm(lang==='ar'?'حذف التخطيط؟':'Delete plan?'))return;try{await api('/api/plans/'+id0,{method:'DELETE'});page('planning')}catch(e){toast(e.message)}}
window.teacherUnits = async function teacherUnits(v){const c=TC(),rows=await api('/api/units'),classes=await api('/api/classes'),plans=await api('/api/plans');window.__teacherClasses=classes;window.__teacherPlans=plans;v.innerHTML=teacherHero(c.units,c.assigned)+`<div class="teacher-panel"><div class="section-head"><div><h3>${c.units}</h3><p class="muted">${lang==='ar'?'الوحدة كتحدد الرياضة وعدد الحصص والمدة، وكتغذي الجذاذات والحصص.':'Chaque unité définit le sport, le nombre de séances et leur durée.'}</p></div><button class="primary" onclick="teacherUnitForm()">＋ ${c.add}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${c.title}</th><th>${c.sport}</th><th>${c.class}</th><th>${lang==='ar'?'عدد الحصص':'Séances'}</th><th>${c.duration}</th><th>${L('actions')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.title)}</td><td>${esc(r.sport||'')}</td><td>${esc(r.class_name||'')}</td><td>${esc(r.session_count||0)}</td><td>${esc(r.duration_minutes||0)} min</td><td><button class="ghost mini" onclick="teacherUnitForm('${r.id}')">${c.edit}</button> <button class="danger mini" onclick="teacherUnitDelete('${r.id}')">${lang==='ar'?'حذف':'Supprimer'}</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">${c.no}</td></tr>`}</tbody></table></div></div>`}
window.teacherUnitForm = function teacherUnitForm(id0){const c=TC(),x=(window.__teacherUnits||[]).find(a=>a.id===id0),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal"><div class="modal-head"><h3>${id0?c.edit:c.add} · ${c.units}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field full"><label>${c.title}</label><input name="title" value="${esc(x?.title||'Unité EPS')}" required></div><div class="field"><label>${lang==='ar'?'الخطة':'Plan'}</label><select name="plan_id" required>${(window.__teacherPlans||[]).map(p=>`<option value="${p.id}" ${x?.plan_id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="field"><label>${c.class}</label><select name="class_id" required>${(window.__teacherClasses||[]).map(p=>`<option value="${p.id}" ${x?.class_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>${c.sport}</label><input name="sport" value="${esc(x?.sport||'')}" required></div><div class="field"><label>${lang==='ar'?'عدد الحصص':'Nombre de séances'}</label><input name="session_count" type="number" min="1" value="${x?.session_count||12}"></div><div class="field"><label>${c.duration}</label><input name="duration_minutes" type="number" value="${x?.duration_minutes||60}"></div><div class="field full"><label>${c.objective}</label><textarea name="objective">${esc(x?.objective||'')}</textarea></div><div class="full"><button class="primary">${c.save}</button></div></form></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));await api(id0?'/api/units/'+id0:'/api/units',{method:id0?'PUT':'POST',body:JSON.stringify(b)});m.remove();page('units')}catch(z){toast(z.message)}}}
window.teacherUnitDelete = async function teacherUnitDelete(id0){if(!confirm(lang==='ar'?'حذف الوحدة؟':'Delete unit?'))return;try{await api('/api/units/'+id0,{method:'DELETE'});page('units')}catch(e){toast(e.message)}}
window.teacherAssessment = async function teacherAssessment(v){const c=TC(),rows=await api('/api/assessments'),classes=await api('/api/classes');window.__teacherClasses=classes;window.__teacherAssessments=rows;v.innerHTML=teacherHero(c.assessment,c.assigned)+`<div class="teacher-panel"><div class="section-head"><div><h3>${c.assessment}</h3><p class="muted">${lang==='ar'?'أدخل نتائج كل نشاط ولكل تلميذ. تُحتسب النتائج تلقائياً ويمكن تصديرها.':'Saisissez les notes par sport et par élève. Les moyennes sont calculées automatiquement.'}</p></div><button class="primary" onclick="teacherAssessmentForm()">＋ ${c.newAssessment}</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${c.date}</th><th>${c.class}</th><th>${c.title}</th><th>${c.criterion}</th><th>${c.scale}</th><th>${L('actions')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.assessment_date)}</td><td>${esc(r.class_name)}</td><td>${esc(r.title)}</td><td>${esc(r.criterion)}</td><td>${esc(r.scale)}</td><td><button class="primary mini" onclick="assessmentMarks('${r.id}')">${lang==='ar'?'النقط':'Notes'}</button> <button class="danger mini" onclick="assessmentDelete('${r.id}')">${lang==='ar'?'حذف':'Supprimer'}</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">${c.no}</td></tr>`}</tbody></table></div></div>`}
window.assessmentMarks = async function assessmentMarks(aid){const a=(window.__teacherAssessments||[]).find(x=>x.id===aid),students=await api('/api/students?class_id='+encodeURIComponent(a.class_id)),old=await api('/api/assessment-results?assessment_id='+encodeURIComponent(aid)),ex=Object.fromEntries(old.map(x=>[x.student_id,x])),m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal wide"><div class="modal-head"><div><h3>${esc(a.title)}</h3><p>${esc(a.class_name)} · /${a.scale}</p></div><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Massar</th><th>${TC().student}</th><th>${lang==='ar'?'النقطة':'Note'}</th><th>${lang==='ar'?'ملاحظة':'Remarque'}</th></tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.massar_number)}</td><td>${esc(s.first_name+' '+s.last_name)}</td><td><input class="mark-input" data-sid="${s.id}" type="number" min="0" max="${a.scale}" step="0.01" value="${ex[s.id]?.score??''}"></td><td><input data-rem="${s.id}" value="${esc(ex[s.id]?.remark||'')}"></td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="primary" id="saveMarks">${TC().save}</button><button class="ghost" onclick="this.closest('.modal').remove()">${TC().cancel}</button></div></div>`;document.body.appendChild(m);m.querySelector('#saveMarks').onclick=async()=>{for(const el of m.querySelectorAll('.mark-input')){if(el.value==='')continue;await api('/api/assessment-results',{method:'POST',body:JSON.stringify({assessment_id:aid,student_id:el.dataset.sid,score:Number(el.value),remark:m.querySelector(`[data-rem="${el.dataset.sid}"]`).value})})}m.remove();toast(TC().save);}
window.assessmentDelete = async function assessmentDelete(id0){if(!confirm(lang==='ar'?'حذف التقويم وكل نقطه؟':'Delete assessment and marks?'))return;await api('/api/assessments/'+id0,{method:'DELETE'});page('assessment')}
window.classReport = async function classReport(cid){const classes=await api('/api/classes'),students=await api('/api/students?class_id='+encodeURIComponent(cid)),sessions=await api('/api/sessions'),daily=await api('/api/daily?session_id='+(sessions.find(s=>s.class_id===cid)?.id||'')).catch(()=>[]),ass=await api('/api/assessments');const cls=classes.find(x=>x.id===cid);const body=`<h1>EPS PILOT — ${lang==='ar'?'تقرير القسم':'Rapport de classe'}</h1><div class="kpi">${cls?.name||''}</div><div class="kpi">${lang==='ar'?'عدد التلاميذ':'Élèves'}: ${students.length}</div><table><tr><th>${lang==='ar'?'Massar':'Massar'}</th><th>${lang==='ar'?'التلميذ':'Élève'}</th><th>${lang==='ar'?'الحضور':'Présence'}</th></tr>${students.map(s=>`<tr><td>${esc(s.massar_number)}</td><td>${esc(s.first_name+' '+s.last_name)}</td><td>—</td></tr>`).join('')}</table><h2>${lang==='ar'?'التقويمات':'Évaluations'}</h2><p>${ass.filter(a=>a.class_id===cid).map(a=>esc(a.title)+' · '+esc(a.assessment_date)).join('<br>')||'—'}</p>`;printHtml('Rapport classe',body)}
window.studentReport = async function studentReport(sid){const d=await api('/api/student-360?student_id='+encodeURIComponent(sid));const st=d.student,att=Object.fromEntries(d.attendance.map(x=>[x.status,x.c])),avg=d.results.length?(d.results.reduce((a,b)=>a+Number(b.score||0),0)/d.results.length).toFixed(2):'—';const body=`<h1>EPS PILOT — ${lang==='ar'?'الملف والتقرير الفردي':'Dossier et rapport individuel'}</h1><div class="kpi">${esc(st.first_name+' '+st.last_name)}</div><div class="kpi">Massar: ${esc(st.massar_number)}</div><div class="kpi">${lang==='ar'?'المعدل':'Moyenne'}: ${avg}</div><h2>${lang==='ar'?'الحضور والحالات':'Présence et statuts'}</h2><p>${Object.entries(att).map(([k,v])=>`${k}: ${v}`).join(' · ')||'—'}</p><h2>${lang==='ar'?'التقويم':'Évaluation'}</h2><table><tr><th>${lang==='ar'?'التاريخ':'Date'}</th><th>${lang==='ar'?'التقويم':'Évaluation'}</th><th>${lang==='ar'?'النقطة':'Note'}</th></tr>${d.results.map(r=>`<tr><td>${esc(r.assessment_date)}</td><td>${esc(r.title)}</td><td>${esc(r.score)}/${esc(r.scale)}</td></tr>`).join('')}</table><h2>${lang==='ar'?'المعطيات الصحية':'Données de santé'}</h2><div class="note">${lang==='ar'?'هذه المعطيات محمية وتظهر فقط حسب الصلاحيات.':'Données protégées selon les autorisations.'}</div>`;printHtml('Student report',body)}
window.teacherReports = async function teacherReports(v){const c=TC(),d=await api('/api/teacher/statistics'),classes=await api('/api/classes'),students=await api('/api/students');const sm=Object.fromEntries((d.sessions||[]).map(x=>[x.status,x.c])),dm=Object.fromEntries((d.daily||[]).map(x=>[x.status,x.c]));window.__reportClasses=classes;window.__reportStudents=students;const total=Object.values(dm).reduce((a,b)=>a+b,0)||1;const bar=(label,val,max)=>`<div class="stat-bar-row"><span>${esc(label)}</span><div><i style="width:${Math.max(2,Math.round((val/max)*100))}%"></i></div><b>${val}</b></div>`;v.innerHTML=teacherHero(c.reports,c.assigned)+`<div class="teacher-panel"><div class="teacher-toolbar"><select id="reportClass"><option value="">${lang==='ar'?'كل الأقسام':'Toutes les classes'}</option>${classes.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="reportStudent"><option value="">${lang==='ar'?'كل التلاميذ':'Tous les élèves'}</option>${students.map(x=>`<option value="${x.id}">${esc(x.first_name+' '+x.last_name)} · ${esc(x.massar_number)}</option>`).join('')}</select><button class="primary" id="aiReport">${lang==='ar'?'تحليل':'Analyse intelligente'}</button><button class="ghost" id="printReport">${lang==='ar'?'طباعة':'Imprimer'}</button><button class="ghost" id="csvReport">Excel / CSV</button></div></div><div class="teacher-kpi-grid"><div class="teacher-kpi"><span>${c.sessions}</span><b>${Object.values(sm).reduce((a,b)=>a+b,0)}</b></div><div class="teacher-kpi"><span>${c.present}</span><b>${dm.present||0}</b></div><div class="teacher-kpi"><span>${c.absent}</span><b>${dm.absent||0}</b></div><div class="teacher-kpi"><span>${c.assessment}</span><b>${d.assessments||0}</b></div></div><div class="stats-grid"><div class="teacher-panel"><h3>${lang==='ar'?'الحصص':'Séances'}</h3>${bar('مخططة',sm.planned||0,Math.max(1,...Object.values(sm)))}${bar('منجزة',sm.completed||0,Math.max(1,...Object.values(sm)))}${bar('غير منجزة',sm.needs_reason||0,Math.max(1,...Object.values(sm)))}</div><div class="teacher-panel"><h3>${lang==='ar'?'حالات التلاميذ':'Statuts des élèves'}</h3>${bar(c.present,dm.present||0,total)}${bar(c.absent,dm.absent||0,total)}${bar(c.uniform,dm.uniform||0,total)}${bar(c.sick,dm.sick||0,total)}${bar(c.late,dm.late||0,total)}${bar(c.otherStatus,dm.other||0,total)}</div><div class="teacher-panel"><h3>${lang==='ar'?'التلاميذ حسب القسم':'Élèves par classe'}</h3>${classes.map(x=>{const n=students.filter(s=>s.class_id===x.id).length;return bar(x.name,n,Math.max(1,...classes.map(q=>students.filter(s=>s.class_id===q.id).length))) }).join('')}</div><div class="teacher-panel"><h3>${lang==='ar'?'التقارير الفردية':'Rapports individuels'}</h3><div class="actions">${students.slice(0,12).map(s=>`<button class="ghost mini" onclick="studentReport('${s.id}')">${esc(s.first_name+' '+s.last_name)}</button>`).join('')}</div></div></div>`;v.querySelector('#aiReport').onclick=async()=>{const cl=v.querySelector('#reportClass').value,st=v.querySelector('#reportStudent').value;if(st){const d=await api('/api/student-360?student_id='+encodeURIComponent(st));const avg=d.results.length?(d.results.reduce((a,b)=>a+Number(b.score||0),0)/d.results.length).toFixed(2):'—';toast(lang==='ar'?`تحليل التلميذ: معدل ${avg}، حضور ${Object.values(Object.fromEntries(d.attendance.map(x=>[x.status,x.c]))).reduce((a,b)=>a+b,0)} سجل.`:`Analyse: moyenne ${avg}`)}else{toast(lang==='ar'?`تحليل القسم/المستوى: ${cl?'القسم المحدد':'جميع الأقسام'} · حصص ${Object.values(sm).reduce((a,b)=>a+b,0)} · حضور ${dm.present||0} · غياب ${dm.absent||0}`:'Analyse générée à partir des données autorisées.')}};v.querySelector('#printReport').onclick=()=>printHtml('EPS PILOT — Reports',v.querySelector('.stats-grid').outerHTML);v.querySelector('#csvReport').onclick=()=>dlText('eps-pilot-rapport.csv',`Indicateur,Valeur\nSessions,${Object.values(sm).reduce((a,b)=>a+b,0)}\nPresent,${dm.present||0}\nAbsent,${dm.absent||0}\nUniform,${dm.uniform||0}\nSick,${dm.sick||0}\nLate,${dm.late||0}`)}
}
window.teacherPortfolio = async function teacherPortfolio(v){const c=TC(),d=await api('/api/profile');const p=d.profile||{},docs=d.documents||[];v.innerHTML=teacherHero(c.portfolio,c.assigned)+`<div class="teacher-panel"><div class="section-head"><div><h3>${lang==='ar'?'الملف المهني':'Dossier professionnel'}</h3><p class="muted">${lang==='ar'?'الملف مرتبط برقم التأجير، كيمشي مع الأستاذ عند الانتقال، ويتجمع سنة بعد سنة.':'Le dossier suit l’enseignant via son numéro de paie.'}</p></div><button class="primary" onclick="professionalDocForm()">＋ ${lang==='ar'?'إضافة دبلوم / وثيقة':'Ajouter diplôme / document'}</button></div><form id="profForm" class="form-grid"><div class="field"><label>${lang==='ar'?'رقم التأجير':'N° de paie'}</label><input name="payroll_number" value="${esc(p.payroll_number||'')}"></div><div class="field"><label>${lang==='ar'?'الدرجة':'Grade'}</label><input name="grade" value="${esc(p.grade||'')}"></div><div class="field"><label>${lang==='ar'?'التخصص':'Spécialité'}</label><input name="specialization" value="${esc(p.specialization||'')}"></div><div class="field"><label>${lang==='ar'?'الأقدمية':'Ancienneté'}</label><input name="seniority" value="${esc(p.seniority||'')}"></div><div class="field full"><label>${lang==='ar'?'ملخص مهني':'Résumé professionnel'}</label><textarea name="professional_summary">${esc(p.professional_summary||'')}</textarea></div><div class="full"><button class="primary">${c.save}</button></div></form><h3>${lang==='ar'?'الوثائق':'Documents'}</h3><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الوثيقة':'Document'}</th><th>${lang==='ar'?'الفئة':'Catégorie'}</th><th>${L('actions')}</th></tr></thead><tbody>${docs.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.category||'')}</td><td><button class="danger mini" onclick="professionalDocDelete('${x.id}')">${lang==='ar'?'حذف':'Supprimer'}</button></td></tr>`).join('')||`<tr><td colspan="3" class="empty">${c.no}</td></tr>`}</tbody></table></div></div>`;v.querySelector('#profForm').insertAdjacentHTML('afterbegin',`<div class="field full"><label>${lang==='ar'?'الصورة المهنية':'Photo professionnelle'}</label><input id="profPhoto" type="file" accept="image/*"><div class="actions"><img src="${esc(p.photo_path||'assets/eps-pilot-logo.png')}" style="width:72px;height:72px;object-fit:cover;border-radius:50%;border:2px solid #b8d5ea"></div></div>`);v.querySelector('#profForm').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));const pf=v.querySelector('#profPhoto')?.files?.[0];if(pf)fd.photo_path=await fileToBase64(pf);await api('/api/teacher/profile',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast(c.save)} }
window.professionalDocForm = function professionalDocForm(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box teacher-modal"><div class="modal-head"><h3>${lang==='ar'?'إضافة وثيقة مهنية':'Ajouter un document'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field full"><label>${lang==='ar'?'العنوان':'Titre'}</label><input name="title" required></div><div class="field"><label>${lang==='ar'?'الفئة':'Catégorie'}</label><select name="category"><option>Diplôme</option><option>Formation</option><option>Attestation</option><option>Certification</option><option>Autre</option></select></div><div class="field"><label>${lang==='ar'?'الرابط/اسم الملف':'Lien / fichier'}</label><input name="file_path"></div><div class="field full"><label>${lang==='ar'?'وصف':'Description'}</label><textarea name="description"></textarea></div><div class="full"><button class="primary">${TC().save}</button></div></form></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();await api('/api/professional-documents',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});m.remove();page('portfolio')}}
