const __V29oldSessions=teacherSessions;
teacherSessions=async function(v){await __V29oldSessions(v);const rows=await api('/api/sessions'),h=v.querySelector('.section-head');if(!h||h.querySelector('[data-v29-export]'))return;h.insertAdjacentHTML('beforeend',`<div class="actions"><button class="ghost" data-v29-export="pdf">PDF</button><button class="ghost" data-v29-export="csv">Excel / CSV</button></div>`);h.querySelector('[data-v29-export="pdf"]').onclick=()=>printHtml('EPS PILOT — Sessions',`<h1>EPS PILOT — ${lang==='ar'?'الحصص':'Séances'}</h1><table><tr><th>Date</th><th>Classe</th><th>Horaire</th><th>Objectif</th><th>Statut</th></tr>${rows.map(x=>`<tr><td>${esc(x.session_date||'')}</td><td>${esc(x.class_name||'')}</td><td>${esc((x.start_time||'')+' - '+(x.end_time||''))}</td><td>${esc(x.objective||'')}</td><td>${esc(x.status||'')}</td></tr>`).join('')}</table>`);h.querySelector('[data-v29-export="csv"]').onclick=()=>dlText('eps-pilot-sessions.csv','Date,Classe,Horaire,Objectif,Statut\n'+rows.map(x=>[x.session_date,x.class_name,(x.start_time||'')+' - '+(x.end_time||''),x.objective||'',x.status||''].map(z=>'"'+String(z??'').replace(/"/g,'""')+'"').join(',')).join('\n'))};


