       unitSel.disabled=!units.length; if(units.length) await renderUnit(units[0].unit.id); else {out.innerHTML='<div class="eps-carnet-empty">لا توجد وحدة مسندة لهذا القسم خلال الشهر المختار وفق التخطيط السنوي.</div>';info.innerHTML='';}
