async function teacherCopilot(v){
 const ar=lang==='ar',fr=lang==='fr';
 v.innerHTML=`<div class="page-title"><div><span class="eyebrow">EPS PILOT · COPILOT</span><h2>${ar?'مساعد EPS PILOT الذكي':fr?'Copilote EPS PILOT':'EPS PILOT Copilot'}</h2><p class="muted">${ar?'اقتراح وضعيات تعلمية وجذاذات قابلة للتعديل انطلاقاً من النشاط والهدف والمستوى.':fr?'Générez des situations d’apprentissage et des fiches modifiables à partir de l’activité, de l’objectif et du niveau.':'Generate editable learning situations and lesson sheets from activity, objective and level.'}</p></div></div>
 <div class="copilot-layout"><div class="card copilot-form-card"><form id="epsCopilotForm" class="form-grid"><div class="field"><label>${ar?'النشاط الرياضي':fr?'Activité': 'Activity'}</label><input name="sport" placeholder="${ar?'مثال: كرة السلة':fr?'Ex. Basketball':'e.g. Basketball'}" required></div><div class="field"><label>${ar?'المستوى':fr?'Niveau':'Level'}</label><input name="level" placeholder="${ar?'مثال: الأولى إعدادي':fr?'Ex. 1AC':'e.g. Grade 7'}"></div><div class="field full"><label>${ar?'هدف الحصة':fr?'Objectif de séance':'Lesson objective'}</label><textarea name="objective" rows="4" required placeholder="${ar?'اكتب الهدف التربوي للحصة...':fr?'Décrivez l’objectif...':'Describe the lesson objective...'}"></textarea></div><div class="field"><label>${ar?'مدة الحصة (دقيقة)':fr?'Durée (min)':'Duration (min)'}</label><input name="duration" type="number" min="20" max="180" value="60"></div><div class="full actions"><button class="primary">${ar?'توليد الحصة الذكية':fr?'Générer la séance':'Generate smart lesson'}</button></div></form></div><div id="copilotOutput" class="card copilot-output"><div class="empty">${ar?'أدخل المعطيات لتوليد اقتراح عملي.':fr?'Saisissez les paramètres pour générer une proposition.':'Enter the parameters to generate a practical proposal.'}</div></div></div>`;
 v.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{const r=await api('/api/teacher/copilot',{method:'POST',body:JSON.stringify({...b,lang})});v.querySelector('#copilotOutput').innerHTML=`<div class="copilot-result"><div class="section-head"><div><span class="eyebrow">EPS PILOT</span><h3>${esc(r.title)}</h3></div><button class="ghost" onclick="printHtml('${esc(r.title).replace(/'/g,"\\'")}',document.getElementById('copilotOutput').innerHTML)">${ar?'طباعة':'Print'}</button></div><p><b>${ar?'الهدف:':fr?'Objectif:':'Objective:'}</b> ${esc(r.objective)}</p><div class="copilot-stages">${r.stages.map((x,i)=>`<div class="copilot-stage"><b>0${i+1}</b><span><strong>${esc(x.name)}</strong><small>${x.minutes} min · ${esc(x.text)}</small></span></div>`).join('')}</div><h4>${ar?'معايير النجاح':'Success criteria'}</h4><ul>${r.success_criteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="muted small">${ar?'المحرك محلي وقابل للتعديل، ولا يقدم تشخيصاً طبياً.':'Local explainable engine; editable output and no medical diagnosis.'}</div></div>`}catch(x){toast(x.message)}};
}
window.teacherCopilot=teacherCopilot;
function teacherIntelligenceTools(v){
 if(v.querySelector('.v40-intel-tools'))return;
 const box=document.createElement('div');box.className='card v40-intel-tools';box.innerHTML=`<div class="section-head"><div><span class="eyebrow">EPS PILOT</span><h3>${lang==='ar'?'أدوات التحليل الذكي':'Smart analysis tools'}</h3></div></div><div class="actions"><button class="ghost" onclick="openClassComparison()">${lang==='ar'?'مقارنة الأقسام':'Compare classes'}</button><button class="ghost" onclick="openReportBuilder()">${lang==='ar'?'منشئ التقارير':'Report builder'}</button></div>`;v.prepend(box);
}
window.openClassComparison=async function(){try{const d=await api('/api/teacher/class-comparison');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box wide"><div class="modal-head"><h3>${lang==='ar'?'مقارنة الأقسام':'Class comparison'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'القسم':'Class'}</th><th>${lang==='ar'?'التلاميذ':'Students'}</th><th>${lang==='ar'?'الحصص':'Sessions'}</th><th>${lang==='ar'?'الغياب':'Absence'}</th><th>${lang==='ar'?'متوسط التقويم':'Assessment avg.'}</th></tr></thead><tbody>${d.classes.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.students}</td><td>${x.sessions}</td><td>${x.absence_entries}</td><td>${x.assessment_average??'—'}</td></tr>`).join('')}</tbody></table></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}};
window.openReportBuilder=async function(){try{const d=await api('/api/teacher/report-builder');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box wide"><div class="modal-head"><h3>${lang==='ar'?'منشئ التقارير الذكي':'Smart report builder'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="card"><h4>${esc(d.title)}</h4>${d.rows.map(x=>`<div class="report-builder-row"><b>${esc(x.class_name)}</b><span>${x.students} ${lang==='ar'?'تلميذ':'students'}</span><span>${x.sessions} ${lang==='ar'?'حصة':'sessions'}</span><span>${x.absence_entries} ${lang==='ar'?'غياب':'absences'}</span><span>${x.assessment_average??'—'} / 20</span></div>`).join('')}</div><div class="actions"><button class="primary" onclick="printHtml('${esc(d.title).replace(/'/g,"\\'")}',this.closest('.modal').querySelector('.card').outerHTML)">${lang==='ar'?'طباعة التقرير':'Print report'}</button></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}};
window.ownerOpsToolbar=function(v){
 if(v.querySelector('.v40-owner-tools'))return; const x=document.createElement('div');x.className='card v40-owner-tools';x.innerHTML=`<div class="section-head"><div><span class="eyebrow">EPS PILOT · CONTROL</span><h3>${lang==='ar'?'أدوات التشغيل والحماية':'Operations & protection'}</h3><p class="muted">${lang==='ar'?'نسخة احتياطية، سجل تدقيق، وإدارة طلبات انتقال الأساتذة.':'Backup, audit trail and teacher transfer management.'}</p></div></div><div class="actions"><button class="primary" onclick="ownerDownloadBackup()">${lang==='ar'?'إنشاء نسخة احتياطية':'Create backup'}</button><button class="ghost" onclick="ownerAuditSummary()">${lang==='ar'?'ملخص سجل التدقيق':'Audit summary'}</button><button class="ghost" onclick="ownerTransfers()">${lang==='ar'?'طلبات انتقال الأساتذة':'Teacher transfers'}</button></div>`;v.prepend(x);
}
window.ownerDownloadBackup=async()=>{try{const r=await fetch('/api/owner/backup',{credentials:'include'});if(!r.ok)throw new Error('Backup failed');const b=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='eps-pilot-backup.sqlite';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast(lang==='ar'?'تم إنشاء النسخة الاحتياطية.':'Backup created.')}catch(e){toast(e.message)}};
window.ownerAuditSummary=async()=>{try{const d=await api('/api/owner/audit-summary');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box wide"><div class="modal-head"><h3>${lang==='ar'?'ملخص سجل التدقيق':'Audit summary'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الإجراء':'Action'}</th><th>${lang==='ar'?'الكيان':'Entity'}</th><th>${lang==='ar'?'العدد':'Count'}</th></tr></thead><tbody>${d.rows.map(x=>`<tr><td>${esc(x.action)}</td><td>${esc(x.entity)}</td><td>${x.count}</td></tr>`).join('')}</tbody></table></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}};
window.ownerTransfers=async()=>{try{const d=await api('/api/owner/transfer-requests');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box wide"><div class="modal-head"><h3>${lang==='ar'?'طلبات انتقال الأساتذة':'Teacher transfer requests'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الأستاذ':'Teacher'}</th><th>${lang==='ar'?'من':'From'}</th><th>${lang==='ar'?'إلى':'To'}</th><th>${lang==='ar'?'الحالة':'Status'}</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.teacher_name)}</td><td>${esc(x.from_name||'—')}</td><td>${esc(x.to_name||'—')}</td><td>${esc(x.status)}</td><td>${x.status==='pending'?`<button class="primary mini" onclick="ownerApproveTransfer('${x.id}','approved');this.disabled=true">${lang==='ar'?'قبول':'Approve'}</button> <button class="danger mini" onclick="ownerApproveTransfer('${x.id}','rejected');this.disabled=true">${lang==='ar'?'رفض':'Reject'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}};
window.ownerApproveTransfer=async(id,status)=>{try{await api('/api/owner/transfer-requests/'+id,{method:'PATCH',body:JSON.stringify({status})});toast(lang==='ar'?'تم تحديث الطلب.':'Request updated.');ownerTransfers()}catch(e){toast(e.message)}};
