window.coordinatorIntelligenceModal=async()=>{try{const d=await api('/api/coordinator/intelligence');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box wide"><div class="modal-head"><h3>${lang==='ar'?'مؤشرات المؤسسة الذكية':'Institution intelligence'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><div class="grid metric-grid"><div class="metric-card"><span>${lang==='ar'?'الأساتذة':'Teachers'}</span><strong>${d.teachers.length}</strong></div><div class="metric-card"><span>${lang==='ar'?'الأقسام':'Classes'}</span><strong>${d.classes.length}</strong></div><div class="metric-card"><span>${lang==='ar'?'الحصص':'Sessions'}</span><strong>${d.sessions}</strong></div><div class="metric-card"><span>${lang==='ar'?'التقارير':'Reports'}</span><strong>${d.reports}</strong></div></div><div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الأستاذ':'Teacher'}</th><th>${lang==='ar'?'الحصص':'Sessions'}</th><th>${lang==='ar'?'التقويم':'Assessments'}</th><th>${lang==='ar'?'الغياب':'Absences'}</th></tr></thead><tbody>${d.teachers.map(x=>`<tr><td>${esc(x.full_name)}</td><td>${x.sessions}</td><td>${x.assessments}</td><td>${x.absences}</td></tr>`).join('')}</tbody></table></div></div>`;document.body.appendChild(m)}catch(e){toast(e.message)}};
// Add a practical health-safety action to the existing student 360 modal without replacing its full health editor.
const __oldShowStudent360=window.showStudent360;
window.showStudent360=async function(r){await __oldShowStudent360(r);const mod=[...document.querySelectorAll('.student-profile-modal')].pop();if(!mod)return;const sId=r?.id;const classText=mod.querySelector('.profile-badges span:nth-child(2)')?.textContent||'';const actions=mod.querySelector('.actions');if(actions&&!actions.querySelector('.health-safety-btn')){const b=document.createElement('button');b.className='ghost health-safety-btn';b.textContent=lang==='ar'?'فحص السلامة الرياضية':'Sport safety check';b.onclick=async()=>{try{const cls=await api('/api/classes');const c=cls.find(x=>x.name===classText);if(!c)return toast(lang==='ar'?'تعذر تحديد القسم.':'Class not found');const d=await api('/api/teacher/sport-safety?class_id='+encodeURIComponent(c.id));const hit=(d.alerts||[]).find(x=>x.student_id===sId);toast(hit?hit.notice:(lang==='ar'?'لا يوجد تنبيه مسجل لهذا التلميذ.':'No recorded alert for this student.'))}catch(e){toast(e.message)}};actions.insertBefore(b,actions.firstChild)}};

function teacherOpsToolbar(v){ return; }
window.openTeacherTransfer=async()=>{try{const insts=await api('/api/institutions');const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${lang==='ar'?'طلب انتقال الأستاذ':'Teacher transfer request'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field full"><label>${lang==='ar'?'المؤسسة المستهدفة':'Target institution'}</label><select name="to_institution_id" required><option value="">—</option>${insts.filter(x=>x.id!==ME.institution_id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="full actions"><button class="primary">${lang==='ar'?'إرسال الطلب':'Send request'}</button><button type="button" class="ghost" onclick="this.closest('.modal').remove()">${lang==='ar'?'إلغاء':'Cancel'}</button></div></form></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/api/teacher/transfer-request',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});m.remove();toast(lang==='ar'?'تم إرسال طلب الانتقال إلى مالك المنصة.':'Transfer request sent to the platform owner.')}catch(x){toast(x.message)}}}catch(e){toast(e.message)}};
function smartPlanningToolbar(v){if(v.querySelector('.v40-smart-planning'))return;const x=document.createElement('div');x.className='card v40-smart-planning';x.innerHTML=`<div class="section-head"><div><span class="eyebrow">EPS PILOT · PLANNING</span><h3>${lang==='ar'?'التخطيط السنوي الذكي':'Smart annual planning'}</h3><p class="muted">${lang==='ar'?'اقتراح بنية وحدات قابلة للتعديل انطلاقاً من النشاط وعدد الأسابيع.':'Generate editable unit structures from activity and weeks.'}</p></div><button class="primary" onclick="openSmartPlanning()">${lang==='ar'?'توليد تخطيط':'Generate plan'}</button></div>`;v.prepend(x)}
window.openSmartPlanning=async()=>{const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${lang==='ar'?'التخطيط السنوي الذكي':'Smart annual planning'}</h3><button class="ghost" onclick="this.closest('.modal').remove()">×</button></div><form class="form-grid"><div class="field"><label>${lang==='ar'?'النشاط':'Activity'}</label><input name="sport" required></div><div class="field"><label>${lang==='ar'?'السنة الدراسية':'School year'}</label><input name="school_year" value="2026-2027"></div><div class="field"><label>${lang==='ar'?'عدد الأسابيع':'Weeks'}</label><input name="weeks" type="number" min="4" max="40" value="20"></div><div class="field"><label>${lang==='ar'?'مدة الحصة':'Duration'}</label><input name="duration" type="number" value="60"></div><div class="full actions"><button class="primary">${lang==='ar'?'توليد':'Generate'}</button></div></form><div id="smartPlanOut"></div></div>`;document.body.appendChild(m);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/teacher/smart-plan',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),lang})});m.querySelector('#smartPlanOut').innerHTML=`<div class="smart-plan-results">${r.units.map(x=>`<div class="report-builder-row"><b>${esc(x.title)}</b><span>${esc(x.sport)}</span><span>${x.session_count} ${lang==='ar'?'حصص':'sessions'}</span><span>${x.duration_minutes} min</span><span>${esc(x.objective)}</span></div>`).join('')}</div>`}catch(x){toast(x.message)}}};

/* ===== V41.4 — authoritative annual-planning UI =====
/* Keep one final implementation after all historical overrides. */
window.teacherPlanning = async function(v){
  const c=TC();
  const [plans,units]=await Promise.all([api('/api/plans'),api('/api/units')]);
  const mine=plans.filter(p=>String(p.teacher_id||'')===String(ME.id));
  const rows=units.filter(u=>mine.some(p=>String(p.id)===String(u.plan_id)));
  const byCycle=[1,2].map(cy=>rows.filter(x=>Number(x.cycle||1)===cy));
  const planInfo=mine[0];
  v.innerHTML=teacherHero(c.planning,lang==='ar'
    ?'هذا التخطيط السنوي مسند إليك من طرف المؤسسة. المعطيات المعتمدة لا يمكن تعديلها من طرف الأستاذ.'
    :'This annual plan is assigned to you by your institution. Approved planning data is read-only for the teacher.')+
    `<div class="teacher-panel v30-panel">
      <div class="section-head"><div>
        <h3>${lang==='ar'?'التخطيط السنوي المسند إليك':'Annual plan assigned to you'}</h3>
        <p class="muted">${planInfo?escHtml(planInfo.title||''):lang==='ar'?'لا يوجد تخطيط سنوي مسند إلى حسابك حالياً.':'No annual plan is currently assigned to your account.'}</p>
      </div>${planInfo?`<span class="status-pill assigned">${lang==='ar'?'مسند':'Assigned'}</span>`:''}</div>
      ${planInfo?byCycle.map((items,idx)=>`<div class="plan-cycle"><div class="plan-cycle-head"><b>${lang==='ar'?'الدورة':'Cycle'} ${idx+1}</b><span>${items.length} ${lang==='ar'?'أنشطة':'activities'}</span></div>
        <div class="table-wrap"><table class="table"><thead><tr><th>${lang==='ar'?'الرياضة':'Sport'}</th><th>${lang==='ar'?'القسم':'Class'}</th><th>${lang==='ar'?'عدد الحصص':'Sessions'}</th><th>${lang==='ar'?'المدة':'Duration'}</th><th>${lang==='ar'?'من':'From'}</th><th>${lang==='ar'?'إلى':'To'}</th></tr></thead><tbody>
        ${items.map(x=>`<tr><td><b>${escHtml(x.sport||x.title||'')}</b></td><td>${escHtml(x.class_name||'—')}</td><td>${x.session_count||0}</td><td>${x.duration_minutes||0} min</td><td>${escHtml(x.start_date||'—')}</td><td>${escHtml(x.end_date||'—')}</td></tr>`).join('')||`<tr><td colspan="6" class="empty">${c.no}</td></tr>`}
        </tbody></table></div></div>`).join(''):
        `<div class="empty-state card"><h3>${lang==='ar'?'لم يتم إسناد تخطيط سنوي إليك بعد':'No annual plan assigned yet'}</h3><p>${lang==='ar'?'عند اعتماد التخطيط من طرف المنسق سيظهر هنا تلقائياً.':'Once the coordinator approves and assigns the plan, it will appear here automatically.'}</p></div>`}
      ${planInfo?`<div class="note">${lang==='ar'?'هذا التخطيط هو المرجع المعتمد للوحدات والحصص والجذاذات والتقويم.':'This plan is the approved reference for units, sessions, lesson sheets and assessment.'}</div>`:''}
    </div>`;
};
